R,C=20,19
g=[[5]*C for _ in range(R)]
for c in range(9,18): g[0][c]=6
for c in range(9): g[19][c]=6
pts=[(4,14),(7,17),(9,16),(14,13),(17,12)]
# bottom bar casts upward
for c in range(9):
    for r in range(19): g[r][c]=9
# top bar downward: all clear rays run to edge; rays containing dots paint through the furthest dot
byc={}
for r,c in pts: byc.setdefault(c,[]).append(r)
for c in range(9,18):
    if c not in byc:
        for r in range(1,20): g[r][c]=9
    else:
        for r in range(1,max(byc[c])+1): g[r][c]=9
        for r in byc[c]: g[r][c]=4
print('\n'.join(' '.join(map(str,row)) for row in g))
